import express from 'express';
import { getConfigManager } from '../../services/ConfigManager';
import { createTelemetryRouter } from '../telemetry';
import { createLibraryRouter } from './index';
import type { LibraryRouteOptions } from './types';
import { authenticateLibrary } from './middleware';
import { createAccountRouter } from '../account';
import { createInstallRefRouter } from '../installRef';
import { createSignInLaunchRouter } from '../signInLaunch';
import { openInSystemBrowser } from '../../utils/systemBrowser';
import { createIntegrationsRouter } from '../integrations';
import { createSupportRouter } from '../support';
import { createPreferencesRouter } from '../preferences';

interface LibraryAppOptions extends LibraryRouteOptions {
  uiDirectory: string;
}

export const createLibraryApp = ({
  uiDirectory,
  ...services
}: LibraryAppOptions) => {
  const app = express();
  app.use('/api/telemetry', createTelemetryRouter(services.telemetry));
  app.use('/api/library', createLibraryRouter(services));
  app.use('/api', createInstallRefRouter());
  app.use(
    '/api',
    createSignInLaunchRouter({
      openExternalUrl: openInSystemBrowser,
      config: getConfigManager(),
    }),
  );
  app.use(
    '/api',
    authenticateLibrary(services.token, services.browserSessions),
    express.json(),
    (req, res, next) => {
      if (
        req.path === '/auth/store' &&
        req.headers.authorization !== `Bearer ${services.token}`
      )
        return res.sendStatus(403);
      next();
    },
    createAccountRouter(services.telemetry),
    createPreferencesRouter(),
    createIntegrationsRouter({ openExternalUrl: openInSystemBrowser }),
    createSupportRouter(services.telemetry),
  );
  app.use('/rivet', express.static(uiDirectory, { index: false }));
  app.use(express.static(uiDirectory, { index: false }));
  app.get(/^\/rivet\/library(?:\/.*)?$/, (_req, res) =>
    res.sendFile('index.html', { root: uiDirectory }),
  );
  app.get('/', (_req, res) => res.redirect('/rivet/library'));
  return app;
};
